(function(root,f){const x=f();if(typeof module==='object')module.exports=x;else root.OmniThemeCore=x})(globalThis,()=>{'use strict';function mode(value,dark){if(!['system','dark','light'].includes(value))throw Error('INVALID_MODE');return value==='dark'||value==='system'&&dark?1:0}function safePrompt(element){if(!element||element.matches('#onetrust-banner-sdk,#CybotCookiebotDialog,[data-consent]')||element.closest('#onetrust-banner-sdk,#CybotCookiebotDialog,[data-consent]'))return false;if(element.querySelector('input[type=password],iframe,[data-consent],#onetrust-reject-all-handler,#CybotCookiebotDialogBodyButtonDecline'))return false;return !/cookie|consent|sign\s*in|log\s*in|paywall|subscribe\s+to\s+read|captcha/i.test(element.textContent.slice(0,4000))}return{mode,safePrompt}});
